    e.preventDefault();
    if (!businessName || !niche) return;

    setLoading(true);
    try {
      const data = await generateMarketingStrategy(businessName, niche);
      setResult(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
