            Start Your Project
          </a>
        </div>
      </section>
    </>
  );

  const renderContent = () => {
    switch (currentView) {
      case 'services':
        return <ServicesPage />;
      case 'team':
        return <TeamPage />;
      case 'home':
      default:
        return renderHome();
    }
  };

  return (
    <div className="min-h-screen">
      <Navbar currentView={currentView} onNavigate={handleNavigate} />
      <main>
        {renderContent()}
      </main>
      <Footer />
      <ChatWidget />
    </div>
  );
};

