            Start Your Project
          </a>
        </div>
      </section>
    </>
  );

  const renderContent = () => {
    switch (currentView) {
      case 'services':
        return <ServicesPage />;
      case 'team':
        return <TeamPage />;
      case 'home':
      default:
        return renderHome();
    }
