        <div className="absolute bottom-[20%] left-[-10%] w-[40%] h-[40%] bg-blue-600/10 rounded-full blur-[120px]"></div>
        <div className="absolute bottom-0 right-0 w-[30%] h-[30%] bg-pink-600/10 rounded-full blur-[120px]"></div>
      </div>

      <div className="relative z-10">
        <Hero onNavigate={handleNavigate} />
        <Services />
        <Portfolio />
        <StrategyLab />
        <Team />
        <Testimonials onNavigate={handleNavigate} />
