import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Services from './components/Services';
import Portfolio from './components/Portfolio';
import Team from './components/Team';
import StrategyLab from './components/StrategyLab';
import Testimonials from './components/Testimonials';
import Footer from './components/Footer';
import ChatWidget from './components/ChatWidget';
import ContactMapSection from './components/ContactMapSection';
import ServicesPage from './pages/ServicesPage';
import TeamPage from './pages/TeamPage';
import PrivacyPolicyPage from './pages/PrivacyPolicyPage';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'home' | 'services' | 'team' | 'privacy'>('home');
  const [pendingHash, setPendingHash] = useState<string | null>(null);

  const handleNavigate = (view: 'home' | 'services' | 'team' | 'privacy', hash?: string) => {
    setCurrentView(view);
    if (hash) {
      setPendingHash(hash);
    } else {
      setPendingHash(null);
    }
  };

  useEffect(() => {
    if (currentView === 'home' && pendingHash) {
      const element = document.querySelector(pendingHash);
      if (element) {
        const timeoutId = setTimeout(() => {
          element.scrollIntoView({ behavior: 'smooth' });
          setPendingHash(null);
        }, 100);
        return () => clearTimeout(timeoutId);
      }
    }
  }, [currentView, pendingHash]);

  const renderHome = () => (
    <>
      <Hero onNavigate={handleNavigate} />
      <Services />
      <Portfolio />
      <StrategyLab />
      <Team />
      <Testimonials onNavigate={handleNavigate} />
      <ContactMapSection />

      <section className="py-24 relative overflow-hidden bg-slate-950">
        <div className="max-w-7xl mx-auto px-6 relative z-10 flex flex-col lg:flex-row items-center justify-between gap-12">
          <div className="glass-effect p-12 md:p-16 rounded-[4rem] w-full flex flex-col lg:flex-row items-center justify-between gap-12 border border-white/5">
            <div className="max-w-2xl text-center lg:text-left">
              <h2 className="text-4xl md:text-6xl font-black text-white mb-6 leading-tight">Let's build something <br /> legendary together.</h2>
              <p className="text-slate-400 text-xl font-medium">Connect with our team to start your transformation journey.</p>
            </div>
            <a href="mailto:hello@novasphere.digital" className="px-12 py-6 bg-indigo-600 text-white rounded-2xl font-black text-xl hover:bg-indigo-500 transition-all shadow-2xl shadow-indigo-600/20 active:scale-95">
              Start Your Project
            </a>
          </div>
        </div>
      </section>
    </>
  );

  const renderContent = () => {
    switch (currentView) {
      case 'services':
        return <ServicesPage />;
      case 'team':
        return <TeamPage />;
      case 'privacy':
        return <PrivacyPolicyPage />;
      case 'home':
      default:
        return renderHome();
    }
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-200 selection:bg-indigo-500/30">
      <Navbar currentView={currentView} onNavigate={handleNavigate} />
      <main>
        {renderContent()}
      </main>
      <Footer currentView={currentView} onNavigate={handleNavigate} />
      <ChatWidget />
    </div>
  );
};

