const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'home' | 'services' | 'team' | 'privacy'>('home');
  const [pendingHash, setPendingHash] = useState<string | null>(null);

  const handleNavigate = (view: 'home' | 'services' | 'team' | 'privacy', hash?: string) => {
    setCurrentView(view);
    if (hash) {
      setPendingHash(hash);
    } else {
      setPendingHash(null);
    }
  };

  useEffect(() => {
    if (currentView === 'home' && pendingHash) {
      const element = document.querySelector(pendingHash);
      if (element) {
        const timeoutId = setTimeout(() => {
          element.scrollIntoView({ behavior: 'smooth' });
          setPendingHash(null);
        }, 100);
        return () => clearTimeout(timeoutId);
      }
    }
  }, [currentView, pendingHash]);

  const renderHome = () => (
    <div className="relative overflow-x-hidden w-full">
      <Hero onNavigate={handleNavigate} />

      {/* Dynamic Background Atmosphere - Layered Glows */}
      <div className="absolute top-[10%] left-0 w-full h-[800px] bg-indigo-600/10 blur-[150px] pointer-events-none rounded-full z-0"></div>
      <div className="absolute top-[30%] right-0 w-[800px] h-[800px] bg-purple-600/5 blur-[150px] pointer-events-none rounded-full z-0"></div>
      <div className="absolute top-[50%] left-1/2 -translate-x-1/2 w-full h-[1000px] bg-indigo-600/5 blur-[150px] pointer-events-none rounded-full z-0"></div>
      <div className="absolute top-[75%] right-1/4 w-[600px] h-[600px] bg-pink-600/5 blur-[130px] pointer-events-none rounded-full z-0"></div>
      <div className="absolute bottom-0 left-0 w-full h-[600px] bg-indigo-600/10 blur-[150px] pointer-events-none rounded-full z-0"></div>

      <div className="relative z-10">
        <Services />
        <Portfolio />
        <StrategyLab />
        <Team />
        <Testimonials onNavigate={handleNavigate} />
        <ContactMapSection />

        {/* Final CTA Section - Resized to Medium */}
        <section className="py-20 relative overflow-hidden bg-transparent">
          <div className="max-w-7xl mx-auto px-6 relative z-10">
            <div className="glass-effect p-10 md:p-16 rounded-[3rem] w-full flex flex-col lg:flex-row items-center justify-between gap-8 border border-white/5 group hover:border-indigo-500/20 transition-all duration-700">
              <div className="max-w-xl text-center lg:text-left">
                <h2 className="text-3xl md:text-5xl font-black text-white mb-4 leading-tight">
                  Let's build something <br /> <span className="gradient-text">legendary</span> together.
                </h2>
                <p className="text-slate-400 text-lg font-medium">
                  Your digital evolution begins with a single conversation.
                </p>
              </div>
              <a 
                href="mailto:hello@novasphere.digital" 
                className="px-10 py-4 bg-indigo-600 text-white rounded-xl font-bold text-lg hover:bg-indigo-500 transition-all shadow-xl shadow-indigo-600/20 active:scale-95 whitespace-nowrap"
              >
                Start Project
              </a>
            </div>
          </div>
        </section>
      </div>
    </div>
  );

  const renderContent = () => {
    switch (currentView) {
      case 'services': return <ServicesPage />;
      case 'team': return <TeamPage />;
      case 'privacy': return <PrivacyPolicyPage />;
      case 'home':
      default: return renderHome();
    }
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-200 selection:bg-indigo-500/30 w-full overflow-x-hidden">
      {/* Global Persistence Layer: Background Texture */}
      <div className="fixed inset-0 pointer-events-none opacity-[0.12] z-0" 
           style={{ backgroundImage: 'radial-gradient(#6366f1 1px, transparent 1px)', backgroundSize: '40px 40px' }}>
      </div>

      <Navbar currentView={currentView} onNavigate={handleNavigate} />

      <main className="relative z-10 w-full">
        <div key={currentView} className="animate-page-enter">
          {renderContent()}
        </div>
      </main>

      <Footer currentView={currentView} onNavigate={handleNavigate} />
      <ChatWidget />
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";

export const generateMarketingStrategy = async (businessName: string, niche: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate a high-level digital marketing strategy for a business named "${businessName}" in the "${niche}" industry. 
      Format the response as a JSON object with these keys: 
      "overview" (a string), "tactics" (an array of strings), "metrics" (an array of strings).`,
      config: {
        responseMimeType: "application/json",
      },
    });

    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const getAssistantResponse = async (history: {role: string, content: string}[], message: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: 'You are Nova, the AI assistant for NovaSphere Digital Agency. You are professional, creative, and expert in web development, AI integration, and digital branding. Keep responses concise and helpful.',
      },
    });

    const response = await chat.sendMessage({ message });
    return response.text;
  } catch (error) {
    console.error("Assistant Error:", error);
    return "I'm having a bit of trouble connecting right now. Could you try again?";
  }
};

import React, { useState } from 'react';

const ContactForm: React.FC = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: ''
  });
  const [status, setStatus] = useState<'idle' | 'sending' | 'submitted' | 'error'>('idle');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus('sending');

    try {
      const response = await fetch('https://formspree.io/f/shubhamchavan@live.com', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify(formData)
      });

      if (response.ok) {
        setStatus('submitted');
        setFormData({ name: '', email: '', message: '' });
        // Reset status after a few seconds
        setTimeout(() => setStatus('idle'), 5000);
      } else {
        setStatus('error');
        setTimeout(() => setStatus('idle'), 5000);
      }
    } catch (err) {
      console.error('Form submission error:', err);
      setStatus('error');
      setTimeout(() => setStatus('idle'), 5000);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  return (
    <section className="py-24 relative overflow-hidden">
      <div className="max-w-3xl mx-auto px-6">
        <div className="glass-effect rounded-[3rem] p-8 md:p-16 border border-white/5 relative z-10">
          <div className="text-center mb-12">
            <div className="inline-flex items-center gap-2 mb-4">
              <span className="w-8 h-[1px] bg-indigo-500"></span>
              <span className="text-indigo-400 font-bold uppercase tracking-[0.3em] text-[10px]">Get In Touch</span>
            </div>
            <h2 className="text-4xl md:text-5xl font-black text-white mb-4">Start a <span className="gradient-text">Conversation</span></h2>
            <p className="text-slate-400 text-lg">Let's discuss how we can engineer your next digital breakthrough.</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 ml-1">Full Name</label>
                <input 
                  type="text" 
                  name="name"
                  required
                  value={formData.name}
                  onChange={handleChange}
                  className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all placeholder:text-slate-600"
                  placeholder="John Doe"
                />
              </div>
              <div className="space-y-2">
                <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 ml-1">Email Address</label>
                <input 
                  type="email" 
                  name="email"
                  required
                  value={formData.email}
                  onChange={handleChange}
                  className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all placeholder:text-slate-600"
                  placeholder="john@example.com"
                />
              </div>
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 ml-1">Message</label>
              <textarea 
                name="message"
                required
                rows={5}
                value={formData.message}
                onChange={handleChange}
                className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all placeholder:text-slate-600 resize-none"
                placeholder="Tell us about your project goals..."
              />
            </div>

            <button 
              type="submit"
              disabled={status === 'sending' || status === 'submitted'}
              className={`w-full py-5 rounded-2xl font-black text-sm uppercase tracking-widest transition-all shadow-xl active:scale-95 flex items-center justify-center gap-3 ${
                status === 'submitted' 
                ? 'bg-emerald-600 text-white cursor-default' 
                : status === 'error'
                ? 'bg-rose-600 text-white'
                : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-indigo-600/20'
              }`}
            >
              {status === 'sending' && <i className="fa-solid fa-circle-notch animate-spin"></i>}
              {status === 'submitted' && <i className="fa-solid fa-check"></i>}
              {status === 'error' && <i className="fa-solid fa-triangle-exclamation"></i>}

